// Bosanski (latinica, razumljivo i za hrvatski i srpski) – preveden iz de.js (15.10.2026). Jezik iz lokala, kratko.
// Bosnisch (lateinisch, für Kroatisch- und Serbischsprachige leicht verständlich) – aus de.js übersetzt (15.10.2026). Ladensprache, kurz.

// Množina: 1 → jedan, 2–4 → dva, 5+ (i 11–14) → pet. Npr. pl(n, "dan", "dana", "dana").
const pl = (n, jedan, dva, pet) => {
  const x = Math.abs(Math.trunc(Number(n))) || 0; const d = x % 10, s = x % 100;
  return d === 1 && s !== 11 ? jedan : d >= 2 && d <= 4 && (s < 12 || s > 14) ? dva : pet;
};

